-- ============================================================
-- BROC scope pack — EU CBAM and EUDR, Annex I code lists
-- Prepared 2026-11-20 from the consolidated legal texts on EUR-Lex.
-- ============================================================
-- What this is: the CN/HS codes CBAM and the EUDR cover, as cited scope
-- rules for ONE workspace. It is data, not schema: run it in the SQL editor
-- when you want these rules, not as a migration. Re-runnable — codes already
-- listed are left alone.
--
-- Before running: set the workspace name on the marked line below.
--
-- How the legal lists were turned into prefixes (so anyone can check):
--   * "Except" lists are expanded into the headings that remain. CBAM's
--     "Chapter 72, except 7202 2, 7202 30 00 ... 7202 99, 7204" becomes
--     7201, 7202 11/19/41/49/60, 7203, 7205-7229. CBAM's "3105 except
--     3105 60 00" becomes the other 3105 subheadings.
--   * An 8-digit CN code ending in 00 covers the whole 6-digit HS
--     subheading, so it is entered at 6 digits (labelled with the CN code).
--     A 6-digit rule also matches HS and US HTS codes on a product.
--   * Codes with further CN digits (2507 00 80, 4012 90 30, 9401 91 90)
--     are entered as CN and only match a CN code.
--   * "ex" entries (only part of a code is covered: cattle only, oil palm
--     only, wood only) are entered at the full code and labelled "ex:". They
--     flag every product under the code; a person decides whether a flagged
--     product is really made from the commodity. Over-flagging is the safe
--     direction for a screening list.
--   * EUDR: Regulation (EU) 2025/2650 deleted ex 49 (printed matter).
--     Delegated Regulation (EU) 2026/2102 (OJ 17.9.2026) deleted ex 4010,
--     ex 4016, ex 4101, ex 4104, ex 4107; narrowed 4012 to 4012 90 30 and
--     1201 to 1201 90 00; and replaced ex 9401 with six listed subheadings.
--     Its ADDITIONS apply from 30 December 2027 and are at the end of this
--     file, commented out.
--   * CBAM: the only amendment to Annex I so far is Regulation (EU)
--     2025/2083, which made 2507 00 80 an "ex" entry (calcined clay only).
--     The proposed downstream extension (COM(2025) 989) is not yet law.
--
-- Not legal advice. Tariff classification is decided by customs; check the
-- Official Journal before relying on this for a filing.
-- ============================================================

DO $$
DECLARE
  -- ▼▼▼ Set your workspace name here (case and extra spaces don't matter) ▼▼▼
  v_name  TEXT := 'YOUR WORKSPACE NAME';
  -- ▲▲▲
  v_org   UUID;
  v_count INT;
BEGIN
  SELECT count(*), min(id::text)::uuid INTO v_count, v_org FROM organizations
   WHERE lower(trim(name)) = lower(trim(v_name)) AND sandbox_of IS NULL;
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'Scope pack not loaded: % workspace(s) named "%". Workspaces here: %',
      v_count, v_name,
      (SELECT string_agg('"' || name || '"', ', ' ORDER BY name) FROM organizations WHERE sandbox_of IS NULL)
      USING HINT = 'Set v_name at the top of the file to one of those names exactly, then run it again.';
  END IF;

  INSERT INTO compliance_scope_rules
    (organization_id, regulation, code_system, cn_prefix, label, source_citation, source_url, last_verified)
  SELECT v_org, r.regulation, r.code_system, r.prefix, r.label, r.citation, r.url, DATE '2026-11-20'
  FROM (VALUES
    -- CBAM — cement
    ('cbam', 'cn', '25070080', 'Calcined clay (ex 2507 00 80: calcined kaolinic clays only)', 'Regulation (EU) 2023/956, Annex I point 1 (consolidated text of 20.10.2025, as amended by Regulation (EU) 2025/2083)', 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02023R0956-20251020'),
